        // This makes totalFee = 10 and burnFee = 10, so totalFee == burnFee
        SPOOKYHALLOWEENFLOKI(TARGET).setFees_base1000(0, 0, 0, 0, 10, 0);

        // Set a low swap threshold that we can afford (1000 tokens with 9 decimals)
